/*
 * Generic weak implementation of arch_syscall_oops.
 * Architectures should provide their own implementation if they need
 * to convert the syscall stack frame (ssf_ptr) into an arch_esf.
 * This weak implementation prevents linker errors if CONFIG_USERSPACE
 * is enabled but an architecture-specific arch_syscall_oops is missing.
 */
FUNC_NORETURN __weak void arch_syscall_oops(void *ssf_ptr)
{
	ARG_UNUSED(ssf_ptr);
	z_fatal_error(K_ERR_KERNEL_OOPS, NULL);
	CODE_UNREACHABLE;
}
